/* main.c */
#include <stdio.h>
#include "geometry.h"

int rectangle_area(int width, int height)
{
    return width * height;
}

int main(void)
{
    printf("area=%d\n", rectangle_area(4, 3));
    return 0;
}

#include <stdio.h>
#define SQUARE(value) ((value) * (value))

static int square(int value)
{
    return value * value;
}

int main(void)
{
    int number = 5;
    printf("macro=%d function=%d\n", SQUARE(number), square(number));
    return 0;
}
